-- 010: Thai financial-proxy library (GLOBAL entries: organization_id IS NULL, read-only in the app).
--
-- Additive and idempotent: each row is inserted only if no global entry with the same name exists, so running this on a
-- database that already has them (for example loaded with bin/load-proxies.php) changes nothing and creates no duplicates.
-- It never deletes or edits existing rows. To update a rate later, edit database/proxies/th-2569.json and run
-- `php bin/load-proxies.php` (it updates changed entries). This file is a snapshot of that JSON as researched in Nov 2026;
-- every entry carries its source, a link and its limitations. Re-check the rates against their sources before reports.

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่าจ้างขั้นต่ำรายวัน จังหวัดพิษณุโลก', 'ค่าจ้างขั้นต่ำตามกฎหมายต่อวันของลูกจ้างในจังหวัดพิษณุโลก ใช้เป็นฐานต่ำสุดของมูลค่าแรงงาน หรือรายได้ที่เสียไป/ได้เพิ่ม', 'Employment and income', 'บาท / คน / วัน', 'THB', 352, 'จังหวัดพิษณุโลก', 2025, 'ประกาศคณะกรรมการค่าจ้าง เรื่อง อัตราค่าจ้างขั้นต่ำ (ฉบับที่ 14) มีผลตั้งแต่ 1 กรกฎาคม 2568', 'https://www.empeo.com/blog/hrm/minimum-wage-thailand-2026/', 'เป็นค่าจ้างขั้นต่ำตามกฎหมาย ไม่ใช่ค่าจ้างตลาดจริง งานที่ใช้ทักษะสูงมีค่าจ้างสูงกว่า อัตรานี้อ่านจากเว็บไซต์รวบรวมข้อมูล ไม่ใช่ราชกิจจานุเบกษา ควรตรวจกับประกาศฉบับจริงและตรวจว่ามีประกาศใหม่หรือไม่ (ที่ตรวจเมื่อ พ.ย. 2569 รายงานว่ายังไม่มีประกาศใหม่)'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่าจ้างขั้นต่ำรายวัน จังหวัดพิษณุโลก');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'มูลค่าเวลารายชั่วโมง (คำนวณจากค่าจ้างขั้นต่ำ จังหวัดพิษณุโลก)', 'มูลค่าต่อชั่วโมงของเวลาอาสาสมัคร เวลาที่ได้คืน หรือเวลาที่เสียไป เมื่อเวลานั้นถูกนำไปทำงานหรือดูแลคนจริง', 'Time savings', 'บาท / คน / ชั่วโมง', 'THB', 44, 'จังหวัดพิษณุโลก', 2025, 'คำนวณ: ค่าจ้างขั้นต่ำ 352 บาท/วัน ÷ 8 ชั่วโมง (ประกาศคณะกรรมการค่าจ้าง ฉบับที่ 14)', 'https://www.empeo.com/blog/hrm/minimum-wage-thailand-2026/', 'ค่าที่คำนวณเอง โดยสมมติวันทำงาน 8 ชั่วโมง เป็นค่าต่ำสุดจึงเหมาะกับเวลาอาสาหรือเวลาที่ได้คืนไปทำงานจริง ไม่เหมาะกับงานวิชาชีพที่ค่าจ้างสูงกว่า ถ้าเป็นเวลาว่างที่ไม่ได้ใช้ทำงาน ไม่ควรให้ค่าเต็ม'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'มูลค่าเวลารายชั่วโมง (คำนวณจากค่าจ้างขั้นต่ำ จังหวัดพิษณุโลก)');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่าไฟฟ้าเรียกเก็บเฉลี่ย (ไม่รวม VAT)', 'ค่าไฟฟ้าเฉลี่ยต่อหน่วย (กิโลวัตต์ชั่วโมง) ที่เรียกเก็บทุกประเภทผู้ใช้ ใช้ประเมินมูลค่าไฟฟ้าที่ประหยัดได้', 'Energy efficiency', 'บาท / kWh', 'THB', 3.86, 'ประเทศไทย', 2026, 'คณะกรรมการกำกับกิจการพลังงาน (กกพ.) ค่าไฟฟ้าเรียกเก็บเฉลี่ย งวดกันยายน–ธันวาคม 2569 (ค่าไฟฐาน + ค่า Ft)', 'https://www.thansettakij.com/economy/energy/666404', 'เป็นค่าเฉลี่ยทุกประเภทผู้ใช้ ไม่รวม VAT 7% ค่าไฟปรับทุก 4 เดือน ส่วนบ้านอยู่อาศัยใช้อัตราก้าวหน้า (200 หน่วยแรกไม่เกิน 3 บาท/หน่วย) ครัวเรือนที่ใช้ไฟน้อยจึงมีค่าจริงต่อหน่วยต่ำกว่านี้ ข้อมูลอ่านจากข่าวที่อ้างอิง กฟผ. ควรตรวจกับประกาศ กกพ.'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่าไฟฟ้าเรียกเก็บเฉลี่ย (ไม่รวม VAT)');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ราคาคาร์บอนเครดิต T-VER เฉลี่ย', 'ราคาซื้อขายเฉลี่ยของคาร์บอนเครดิตในตลาดสมัครใจของไทย ใช้ประเมินมูลค่าก๊าซเรือนกระจกที่ลดหรือกักเก็บได้', 'Environmental benefits', 'บาท / tCO2e', 'THB', 144.28, 'ประเทศไทย (ตลาดคาร์บอนภาคสมัครใจ T-VER)', 2025, 'องค์การบริหารจัดการก๊าซเรือนกระจก (อบก.) ราคาซื้อขายเฉลี่ย 6 เดือนแรกปีงบประมาณ 2568 (ต.ค. 2567 – มี.ค. 2568)', 'https://www.thansettakij.com/sustainable/net-zero/626583', 'เป็นราคาซื้อขายแบบทวิภาค (OTC) ที่ปริมาณซื้อขายน้อย ราคาต่างกันมากตามประเภทโครงการ (ไตรมาสแรกปีงบ 2568 เฉลี่ย 174.52 บาท ส่วนช่วง ต.ค. 2566 – มี.ค. 2567 ชีวมวลซื้อขาย 46–85 บาท/ตัน) ควรใช้ค่าต่ำแบบอนุรักษ์นิยม ถ้าโครงการขายคาร์บอนเครดิตจริงห้ามนับซ้ำเป็นรายได้ และควรตรวจราคาล่าสุดจาก อบก.'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ราคาคาร์บอนเครดิต T-VER เฉลี่ย');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'อัตราจ่ายค่าบริการผู้ป่วยใน บัตรทอง (สปสช.)', 'อัตราที่กองทุนหลักประกันสุขภาพแห่งชาติจ่ายชดเชยค่าบริการผู้ป่วยในต่อ 1 หน่วยน้ำหนักสัมพัทธ์ปรับ (AdjRW) ใช้เป็นฐานต่ำของต้นทุนการนอนโรงพยาบาลที่หลีกเลี่ยงได้', 'Health and wellbeing', 'บาท / AdjRW', 'THB', 8350, 'ประเทศไทย', 2026, 'สำนักงานหลักประกันสุขภาพแห่งชาติ (สปสช.) อัตราจ่ายผู้ป่วยใน ปีงบประมาณ 2569 (บอร์ด สปสช. ยืนยัน 3 พ.ย. 2568)', 'https://policywatch.thaipbs.or.th/article/life-213', 'เป็นอัตราจ่ายชดเชยของกองทุน ไม่ใช่ต้นทุนจริงของโรงพยาบาล (ต้นทุนจริงสูงกว่า ดูรายการต้นทุนต่อ AdjRW) ต้องคูณกับ AdjRW ของโรคที่หลีกเลี่ยงได้ ไม่ใช่ต่อครั้ง มีรายงานว่าปีงบประมาณ 2570 บอร์ดเห็นชอบแนวทางจ่าย 10,000 บาท/AdjRW ควรตรวจประกาศล่าสุด'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'อัตราจ่ายค่าบริการผู้ป่วยใน บัตรทอง (สปสช.)');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ต้นทุนผู้ป่วยใน เฉลี่ยต่อ AdjRW: โรงพยาบาลชุมชนแม่ข่าย', 'ต้นทุนเฉลี่ยของการรักษาผู้ป่วยในต่อ 1 AdjRW ของโรงพยาบาลชุมชนแม่ข่าย', 'Health and wellbeing', 'บาท / AdjRW', 'THB', 13721, 'ประเทศไทย', NULL, 'TDRI การศึกษาต้นทุนโรงพยาบาลรัฐไทย (รายงานข่าว Hfocus เมษายน 2569)', 'https://www.hfocus.org/content/2026/04/37608', 'เป็นค่าเฉลี่ยจากการศึกษาของ TDRI ที่อ่านจากข่าว ไม่ใช่รายงานฉบับเต็ม และข่าวไม่ระบุปีของข้อมูลต้นทุน (จึงเว้นปีอ้างอิงไว้) ควรอ่านรายงานฉบับเต็มก่อนใช้ ต้องคูณกับ AdjRW ของกรณี และควรเลือกประเภทโรงพยาบาลที่ผู้ป่วยจะใช้บริการจริง'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ต้นทุนผู้ป่วยใน เฉลี่ยต่อ AdjRW: โรงพยาบาลชุมชนแม่ข่าย');

