WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ต้นทุนผู้ป่วยใน เฉลี่ยต่อ AdjRW: โรงพยาบาลสังกัดมหาวิทยาลัย');

