INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'เงินเดือนแรกบรรจุข้าราชการ วุฒิปริญญาตรี', 'เงินเดือนเริ่มต้นต่อเดือนของข้าราชการแรกบรรจุวุฒิปริญญาตรี ใช้เป็นฐานต่ำของรายได้เริ่มต้นของบัณฑิตที่ได้งานเพิ่มขึ้น', 'Employment and income', 'บาท / คน / เดือน', 'THB', 18150, 'ประเทศไทย', 2025, 'สำนักงาน ก.พ. (รายงานข่าว) เงินเดือนแรกบรรจุหลังปรับขึ้น 10% ต่อเนื่อง 2 ปี (1 พ.ค. 2567 และ 1 พ.ค. 2568)', 'https://thethaiger.com/th/news/1580860/', 'เป็นอัตราของระบบข้าราชการ (ช่วง 18,150–19,970 บาท ตามประเภทวุฒิ) ใช้เป็นค่าต่ำของรายได้เริ่มต้น ไม่ใช่ค่าเฉลี่ยของตลาดแรงงานเอกชน ข้อมูลอ่านจากข่าว ควรตรวจกับ ก.พ.'
