INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่าสมนาคุณวิทยากร (บุคลากรของรัฐ) เพดานตามระเบียบกระทรวงการคลัง', 'เพดานค่าสมนาคุณวิทยากรที่เป็นบุคลากรของรัฐ ต่อชั่วโมง ใช้ประเมินมูลค่าการอบรมที่ผู้เข้าร่วมได้รับ', 'Education', 'บาท / ชั่วโมง', 'THB', 600, 'ประเทศไทย', NULL, 'ระเบียบกระทรวงการคลังว่าด้วยการเบิกจ่ายค่าใช้จ่ายในการฝึกอบรม (อ้างอิงในเอกสารกรอบอัตราของสำนักงานคณะกรรมการวิจัยแห่งชาติ)', 'https://www.nriis.go.th/FileUpload/AttatchFile/News/256511021035174577165.pdf', 'เป็นเพดานการเบิกจ่ายภาครัฐ ไม่ใช่ราคาตลาด วิทยากรผู้ทรงคุณวุฒิเป็นพิเศษอาจจ่ายสูงกว่าเมื่อได้รับอนุมัติ และบางหน่วยงานกำหนดเพดานของตนเองสูงกว่านี้ (เช่น 800 และ 1,600 บาท/ชั่วโมง) ใช้เป็นต้นทุนทดแทนของการอบรม ควรตรวจกฎหมายหรือข้อบังคับที่ใช้ในหน่วยงานของท่าน'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่าสมนาคุณวิทยากร (บุคลากรของรัฐ) เพดานตามระเบียบกระทรวงการคลัง');

