INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ต้นทุนเก็บขนและกำจัดขยะมูลฝอย กรุงเทพมหานคร', 'ต้นทุนต่อกิโลกรัมของการจัดการขยะมูลฝอยของกรุงเทพมหานคร: ค่าเก็บขน 1.46 บาท + ค่ากำจัด 0.82 บาท = 2.28 บาท/กก.', 'Waste management', 'บาท / กก.', 'THB', 2.28, 'กรุงเทพมหานคร', 2023, 'กรุงเทพมหานคร (โพสต์ของที่ปรึกษาผู้ว่าราชการ กทม. เมษายน 2567) ข้อมูลปี 2565–2566', 'https://www.matichon.co.th/local/news_4538650', 'เป็นต้นทุนของกรุงเทพมหานครเท่านั้น ต้นทุนของท้องถิ่นอื่นต่างกัน โดยเฉพาะ อบต. ที่ไม่มีที่กำจัดเอง ควรขอตัวเลขจริงจาก อปท. ในพื้นที่ ข้อมูลอ่านจากข่าวที่อ้างโพสต์ดังกล่าว'
